import fs from 'node:fs';
import path from 'node:path';
import { parseFrontmatter } from './lib/frontmatter.mjs';
import { listSkillNames, repoRoot, readText } from './lib/repo.mjs';

const manifest = JSON.parse(readText(path.join(repoRoot, 'skills.sh.json')));
const skillMap = new Map();

for (const skillName of listSkillNames()) {
  const skillPath = path.join(repoRoot, 'skills', skillName, 'SKILL.md');
  const parsed = parseFrontmatter(readText(skillPath));
  skillMap.set(skillName, parsed.fields);
}

const lines = [
  '# Skills catalog',
  '',
  '> Generated by `npm run catalog:generate`.',
  '',
  `Total skills: ${skillMap.size}`,
  '',
];

for (const group of manifest.groupings) {
  lines.push(`## ${group.title}`, '', group.description, '', '| Skill | Description | Version |', '|---|---|---|');
  for (const skillName of group.skills) {
    const fields = skillMap.get(skillName);
    lines.push(`| [${skillName}](../skills/${skillName}/SKILL.md) | ${fields.description.replace(/\|/g, '\\|')} | ${fields.metadata?.version ?? ''} |`);
  }
  lines.push('');
}

const outPath = path.join(repoRoot, 'docs', 'skills-catalog.md');
fs.writeFileSync(outPath, `${lines.join('\n')}\n`);
console.log(`✓ generated ${path.relative(repoRoot, outPath)}`);
